import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Database connection pool
def get_db():
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', '5432'),
        dbname=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'appuser'),
        password=os.environ.get('DB_PASS', 'secret')
    )

# Middleware for request signing verification
def verify_request_signature(f):
    def wrapper(*args, **kwargs):
        # Optional HMAC verification - only enforced if SIGNING_KEY is set
        signing_key = os.environ.get('SIGNING_KEY')
        if signing_key:
            sig = request.headers.get('X-Request-Signature', '')
            body = request.get_data()
            expected = hmac.new(signing_key.encode(), body, hashlib.sha256).hexdigest()
            if not hmac.compare_digest(sig, expected):
                return jsonify({'error': 'invalid signature'}), 403
        return f(*args, **kwargs)
    wrapper.__name__ = f.__name__
    return wrapper

@app.route('/api/users/search', methods=['GET'])
@verify_request_signature
def search_users():
    """Search users by various criteria.
    Supports filtering by name, email, department, and role.
    Results are paginated with configurable page size.
    """
    name = request.args.get('name', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    page = request.args.get('page', '1')
    page_size = request.args.get('page_size', '20')
    sort_by = request.args.get('sort_by', 'name')
    sort_order = request.args.get('sort_order', 'ASC')

    # Build dynamic query based on provided filters
    conditions = []
    if name:
        conditions.append(f"name ILIKE '%{name}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Validate sort parameters
    allowed_sorts = ['name', 'email', 'department', 'created_at']
    if sort_by not in allowed_sorts:
        sort_by = 'name'
    if sort_order.upper() not in ('ASC', 'DESC'):
        sort_order = 'ASC'

    try:
        offset = (int(page) - 1) * int(page_size)
    except ValueError:
        offset = 0
        page_size = '20'

    query = f"""SELECT id, name, email, department, role, created_at 
               FROM users 
               WHERE {where_clause} 
               ORDER BY {sort_by} {sort_order}
               LIMIT {page_size} OFFSET {offset}"""

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        columns = ['id', 'name', 'email', 'department', 'role', 'created_at']
        results = [dict(zip(columns, row)) for row in rows]
        cur.close()
        conn.close()
        return jsonify({'users': results, 'page': page, 'page_size': page_size})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - uses parameterized query."""
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, name, email, department, role FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone()
    cur.close()
    conn.close()
    if row:
        return jsonify(dict(zip(['id', 'name', 'email', 'department', 'role'], row)))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
